<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;use App\Services\DanceCupScoringService;
Auth::requireAdmin();$test=(string)($_GET['data_mode']??'')==='test';if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin access required.');}$workflow=(string)($_GET['workflow']??'');
$modes=['manual'=>['Manual Scoring','category.php','Open Manual Sheet','dark','✎','Create and score categories entirely in the Manual workflow.'],'automatic'=>['Automatic Scoring','automatic-setup.php','Set Up & Open','primary','⚙','Create categories for secure judge links and live progress.'],'projection'=>['Live Projection','projection-control.php','Open Projection','danger','▣','Control the audience screen for any Dance Cup category.']];
if(!isset($modes[$workflow])){header('Location: ./'.($test?'?data_mode=test':''),true,303);exit;}
$pdo=Database::connection();DanceCupScoringService::ensureWorkspaceTables($pdo,$test);$tables=DanceCupScoringService::tables($test);$sql="SELECT c.id,c.category_name,c.dance_style,c.competition_level,c.entry_type,c.round_name,c.status,c.scoring_mode,e.name event_name,e.event_date FROM {$tables['competitions']} c JOIN {$tables['events']} e ON e.id=c.event_id WHERE e.status<>'archived'";$params=[];if($workflow!=='projection'){$sql.=" AND c.scoring_mode=:mode";$params['mode']=$workflow;}$sql.=" ORDER BY e.event_date DESC,e.id DESC,c.category_name,c.id";$query=$pdo->prepare($sql);$query->execute($params);$categories=$query->fetchAll();
[$label,$route,$actionLabel,$colour,$icon,$description]=$modes[$workflow];$suffix=$test?'&data_mode=test':'';$creationWorkflow=$workflow==='projection'?'manual':$workflow;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($label)?> | Dance Cup</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=398" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=420"></script><style>body{background:#f4f6f9}.workflow-shell{max-width:1350px}.workflow-hero{border:0;border-radius:24px;background:linear-gradient(135deg,#101c35,#5b1833);color:#fff;box-shadow:0 18px 44px rgba(15,23,42,.17)}.workflow-hero h1,.workflow-hero p{color:#fff}.workflow-icon{display:grid;place-items:center;width:62px;height:62px;border-radius:18px;background:rgba(255,255,255,.13);font-size:1.8rem}.category-card{border:1px solid #e0e5ec;border-radius:18px;box-shadow:0 10px 28px rgba(15,23,42,.07)}.category-card .btn{min-height:46px;font-weight:800}.event-name{color:#8b2948;font-weight:800}.meta{display:flex;gap:.45rem;flex-wrap:wrap}.meta span{padding:.3rem .55rem;border-radius:999px;background:#eef2f7;font-size:.78rem;font-weight:700}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./<?=$test?'?data_mode=test':''?>">Dance Cup</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container workflow-shell py-4"><section class="workflow-hero p-4 p-lg-5 mb-4"><div class="d-flex align-items-center gap-3"><div class="workflow-icon"><?=e($icon)?></div><div><div class="text-uppercase small fw-bold text-warning"><?=$test?'TEST · ':''?>DANCE CUP</div><h1 class="h2 mb-1"><?=e($label)?></h1><p class="mb-0 opacity-75"><?=e($description)?></p></div></div></section><div class="d-flex justify-content-between align-items-center gap-2 flex-wrap mb-3"><h2 class="h4 mb-0">Select Category</h2><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="./<?=$test?'?data_mode=test':''?>">← Scoring Options</a><a class="btn btn-warning" href="index.php?workflow=<?=e($creationWorkflow)?><?=$suffix?>"><?=$workflow==='projection'?'Events & Categories':'Create '.$label.' Event / Category'?></a></div></div><div class="row g-3"><?php foreach($categories as $category):?><div class="col-md-6 col-xl-4"><article class="card category-card h-100"><div class="card-body p-4 d-flex flex-column"><div class="event-name small mb-2"><?=e($category['event_name'])?></div><h3 class="h5"><?=e($category['category_name'])?></h3><div class="meta mb-4"><span><?=e(ucwords(str_replace('_',' ',$category['dance_style'])))?></span><span><?=e(ucwords(str_replace('_',' ',$category['competition_level'])))?></span><span><?=e(ucfirst($category['round_name']))?></span><span><?=e(ucfirst($category['status']))?></span><?php if($workflow==='projection'):?><span><?=e(ucfirst($category['scoring_mode']))?> scoring</span><?php endif;?></div><a class="btn btn-<?=e($colour)?> mt-auto" href="<?=e($route)?>?id=<?=(int)$category['id']?><?=$suffix?>"><?=e($actionLabel)?></a></div></article></div><?php endforeach;?><?php if(!$categories):?><div class="col-12"><div class="card category-card"><div class="card-body text-center p-5"><h3 class="h5">No categories in this workflow</h3><p class="text-muted">Create the event and category here; it remains isolated from the other scoring workflow.</p><a class="btn btn-warning" href="index.php?workflow=<?=e($creationWorkflow)?><?=$suffix?>">Create Event / Category</a></div></div></div><?php endif;?></div></main></body></html>
